args.command:
export CDP_PORT=56707
NODE=<node>
CDP=<chrome-cdp-ex>/skills/chrome-cdp-ex/scripts/cdp.mjs
"$NODE" "$CDP" eval E01BFF8F '(() => {
  const set=(n,v)=>{const e=document.querySelector("[name="+n+"]"); e.focus(); e.value=v; e.dispatchEvent(new Event("input",{bubbles:true})); e.dispatchEvent(new Event("change",{bubbles:true}));};
  const cases=[
    ["neg-price","A","item",1,-5],
    ["zero-qty","A","item",0,10],
    ["decimal","A","item",1.5,10],
    ["fullwidth","Ａ","品", "１", "１００"],
    ["spaces","   ","item",1,10],
    ["emoji","🙃","item",1,10]
  ];
  const out=[];
  for (const [name,c,item,q,p] of cases) {
    set("customer", c); set("item", item); set("qty", String(q)); set("price", String(p)); set("note", name);
    out.push({name, sub: document.querySelector("#subtotal").textContent, qty: document.querySelector("[name=qty]").value, price: document.querySelector("[name=price]").value});
  }
  return JSON.stringify(out);
})()'

